package com.brasa.restaurant.mapper;import com.brasa.restaurant.dto.Dtos.*;import com.brasa.restaurant.model.*;import java.util.*;public final class ApiMapper{private ApiMapper(){}public static UsuarioResponse user(Usuario u){return new UsuarioResponse(u.getId(),u.getNome(),u.getEmail(),u.getPerfil());}public static RestauranteResponse restaurant(Restaurante r){return new RestauranteResponse(r.getId(),r.getNome(),r.getSlug(),r.getLogoUrl(),r.getCorPrimaria(),r.getCorDestaque(),r.isAtivo());}public static CategoriaDto category(Categoria c){return new CategoriaDto(c.getId(),c.getNome(),c.getOrdem());}public static ProdutoDto product(Produto p){return new ProdutoDto(p.getId(),p.getCategoriaId(),p.getNome(),p.getDescricao(),p.getPreco(),p.getImagemUrl(),p.isDisponivel());}public static PedidoResponse order(Pedido p){return new PedidoResponse(p.getId(),p.getNumeroMesa(),p.getNomeCliente(),p.getStatus(),p.getTotal(),p.getCriadoEm(),p.getItens().stream().map(i->new ItemPedidoResponse(i.getId(),i.getProdutoId(),i.getNomeProduto(),i.getQuantidade(),i.getPrecoUnitario(),i.getObservacao())).toList());}public static FuncionarioDto employee(Funcionario f){return new FuncionarioDto(f.getId(),f.getNome(),f.getCargo(),f.getTurno(),f.isAtivo());}public static EscalaDto schedule(EscalaSemanal e){return new EscalaDto(e.getFuncionarioId(),e.getSemanaReferencia(),new DiasDto(e.getSeg(),e.getTer(),e.getQua(),e.getQui(),e.getSex(),e.getSab(),e.getDom()));}public static ChamadoResponse call(Chamado c){return new ChamadoResponse(c.getId(),c.getNumeroMesa(),c.getTipo(),c.getStatus(),c.getCriadoEm());}}
